import { chainClient, checkAbort, ChainDataError, logKey } from './client.js';
import { cachedEvents } from './event-store.js';
import { revealedEntries } from './tickets.js';
import { playerAddress, uint } from './state.js';

// Whale/deity grants reach at most 100 levels ahead; boxes at most 51.
// Level L's generation window is stamped at the seal of purchase level L - 1 (audit 26ad5863),
// i.e. about when the game reaches L - 2. The window of level-104 therefore opened while the game
// was still ~six levels short of level-100, so it safely includes even far-future registry
// registrations for this level.
export async function registrationStart(s, level) {
  if (level <= 104) return Number(s.client.chain.deployBlock);
  const start = await s.field('GAME', 'ticketGenerationStartBlock', level - 104);
  if (!start) throw new ChainDataError('Missing level registration window.', 'INCOMPLETE_HISTORY');
  return Number(start);
}
export async function bingoCandidates(s, rawPlayer, { level: selectedLevel, signal } = {}) {
  const player = playerAddress(rawPlayer);
  const current = Number(await s.field('GAME', 'level'));
  // Only level .. level + 2 can hold minted (trait-revealed) tickets: higher levels stay queued
  // unminted in the far-future key space (_mintCeiling, audit 26ad5863).
  const levels = selectedLevel == null ? Array.from({ length: 3 }, (_, i) => current + i) : [uint(selectedLevel)];
  // Levels resolve concurrently: the shared log lane already bounds RPC concurrency, and walking
  // six levels of five log scans each in series outran the panel's read deadline for a whale.
  const perLevel = await Promise.all(levels.map(async level => {
    checkAbort(signal);
    if (await s.field('GAME', 'bingoClaimed', level, player)) return null;
    const batches = await revealedEntries(s, player, level, { signal });
    const masks = new Uint8Array(32);
    for (const batch of batches) for (const trait of batch.traits) masks[((trait >> 6) << 3) | (trait & 7)] |= 1 << ((trait >> 3) & 7);
    for (let symbol = 0; symbol < 32; symbol++) if (masks[symbol] === 255) return { player, level, quadrant: symbol >> 3, symbol, slots: null, proofPending: true };
    return null;
  }));
  const claimable = perLevel.filter(Boolean);
  const events = await cachedEvents(s, 'GAME', 'BingoClaimed', { player }, { fromBlock: await registrationStart(s, current), signal });
  return { player, claimable, claimed: events.map(row => ({
    id: logKey(row), player, level: Number(row.args.level), symbol: Number(row.args.symbol), tier: 'regular',
    flipReward: String(row.args.flipReward), dgnrsPaid: String(row.args.dgnrsPaid), blockNumber: row.blockNumber,
    transactionHash: row.transactionHash, logIndex: row.logIndex,
  })), scope: { fromLevel: levels[0], toLevel: levels.at(-1) } };
}

export async function bingoProof(rawPlayer, rawLevel, rawSymbol, { signal, client = chainClient() } = {}) {
  const player = playerAddress(rawPlayer); const level = uint(rawLevel); const symbol = uint(rawSymbol, 31);
  const s = await client.snapshot({ fresh: true, signal });
  if (await s.field('GAME', 'bingoClaimed', level, player)) throw new ChainDataError('Bingo already claimed.', 'AlreadyClaimed');
  const registrations = await cachedEvents(s, 'GAME', 'EntryOwnerRegistered', { lvl: level, owner: player }, { fromBlock: await registrationStart(s, level), signal });
  const indices = [...new Set(registrations.map(row => Number(row.args.idx)))].sort((a, b) => a - b);
  if (!indices.length) throw new ChainDataError('No registered entries for this Bingo.', 'INCOMPLETE_HISTORY');
  const slots = [];
  for (let color = 0; color < 8; color++) {
    checkAbort(signal); const trait = ((symbol >> 3) << 6) | (color << 3) | (symbol & 7); let found = null;
    for (let group = 0; group < indices.length && found == null; group += 1024) {
      let cursor = 0; let words = 512;
      while (true) {
        checkAbort(signal); let page;
        try { page = await s.call('GAME_LENS', 'findTraitEntry', [client.address('GAME'), level, trait, indices.slice(group, group + 1024), cursor, words]); }
        catch (error) {
          // Public eth_call ceilings differ. Shrink only recognizable budget
          // failures; transport failures must not turn into a missing proof.
          if (words > 1 && /gas|out of|limit|CALL_REVERTED/i.test(`${error.code} ${error.message}`)) { words = Math.max(1, words >> 1); continue; }
          throw error;
        }
        if (page.found) { found = Number(page.position); break; }
        if (page.nextOffset >= page.total) break;
        if (Number(page.nextOffset) <= cursor) throw new ChainDataError('Bingo scan made no progress.');
        cursor = Number(page.nextOffset);
      }
    }
    if (found == null) throw new ChainDataError('This Bingo no longer has all eight colors.', 'INCOMPLETE_HISTORY');
    slots.push(found);
  }
  await s.verify(signal); return slots;
}

// Far-future holdings, remembered per deployment and wallet for the life of the page. They move only
// when that wallet buys or opens something (any `degenerus:tx-confirmed` clears them) — otherwise they
// are re-read only when the salvage view opens (a full scan below refreshes them) or the page reloads.
// Designer call, 2026-09-24: no timed refresh; far-future counts may lag another wallet's buy.
const farHoldingsCache = new Map();
const farHoldingsKey = (s, player) => `${s.client.chain.id}:${s.client.address('GAME')}:${player}`;
export function cachedFarHoldings(s, player) { return farHoldingsCache.get(farHoldingsKey(s, playerAddress(player))) ?? null; }
export function rememberFarHoldings(s, player, rows) {
  const key = farHoldingsKey(s, playerAddress(player)); farHoldingsCache.set(key, rows);
  for (const oldKey of farHoldingsCache.keys()) if (farHoldingsCache.size > 32 && oldKey !== key) farHoldingsCache.delete(oldKey);
}
export function clearFarHoldings() { farHoldingsCache.clear(); }
if (typeof document !== 'undefined') document.addEventListener?.('degenerus:tx-confirmed', clearFarHoldings);

export async function farFutureQueue(s, rawPlayer, { levels, positions = false, signal } = {}) {
  const player = playerAddress(rawPlayer);
  const active = Number(await s.call('GAME_LENS', 'activeTicketLevelOf', [s.client.address('GAME')]));
  // Salvage distance is 2..100 from the active ticket level (MintStreakUtils, audit 26ad5863),
  // and every level that far out is above _mintCeiling(), i.e. in the far-future key space.
  const targets = levels ? levels.map(level => uint(level)) : Array.from({ length: 99 }, (_, i) => active + 2 + i);
  const rows = [];
  // Four small Multicall waves, only when the far-future view is opened.
  for (let i = 0; i < targets.length; i += 25) {
    checkAbort(signal);
    const wave = await Promise.all(targets.slice(i, i + 25).map(async level => {
      if (level < active + 2 || level > active + 100) throw new ChainDataError('Level is outside the salvage window.', 'INVALID_REQUEST');
      const key = level | (1 << 22); const pos = Number(await s.field('GAME', 'entryOwnerPosition', key, player));
      if (!pos) return null;
      const record = await s.field('GAME', 'lvlEntryOwner', level, pos - 1);
      if (record.owner !== player) throw new ChainDataError('Queue owner mismatch.');
      const entryCount = Number((record.owed >> 8n) & 0xffffffffn); const remainder = Number(record.owed & 255n);
      if (!entryCount && !remainder) return null;
      return { level, entryCount, remainder, ownerPosition: pos, queueIndex: null };
    }));
    rows.push(...wave.filter(Boolean));
  }
  if (positions) for (const row of rows) {
    let cursor = 0;
    while (true) {
      checkAbort(signal);
      const page = await s.call('GAME_LENS', 'findQueueEntry', [s.client.address('GAME'), row.level | (1 << 22), row.ownerPosition, cursor, 512]);
      if (page.found) { row.queueIndex = Number(page.position); break; }
      if (page.nextOffset >= page.total || Number(page.nextOffset) <= cursor) throw new ChainDataError('Queue changed while preparing salvage. Refresh and retry.', 'STALE_QUEUE');
      cursor = Number(page.nextOffset);
    }
  }
  // Opening the salvage view scans the whole window — the freshest read there is; keep it.
  if (!levels) rememberFarHoldings(s, player, rows.map(({ queueIndex, ...row }) => row));
  return { player, rows, positionsDeferred: !positions, blockNumber: String(s.block.number) };
}
export async function salvagePositions(player, levels, { signal, client = chainClient() } = {}) {
  const s = await client.snapshot({ fresh: true, signal }); const result = await farFutureQueue(s, player, { levels, positions: true, signal });
  const byLevel = new Map(result.rows.map(row => [row.level, row.queueIndex]));
  const indices = levels.map(level => {
    const position = byLevel.get(Number(level));
    if (position == null) throw new ChainDataError('Selected salvage tickets are no longer held.', 'STALE_QUEUE');
    return position;
  });
  await s.verify(signal); return indices;
}
